import{_ as a,o as s,c as o,a2 as t}from"./chunks/framework.DQbZ8cc1.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"docs/qa.md","filePath":"docs/qa.md"}'),i={name:"docs/qa.md"};function r(n,e,h,l,c,d){return s(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This page focuses on common questions from teams evaluating BBS-GO for forums, Q&amp;A communities, knowledge sharing, and discussions.</p></div><h2 id="what-is-bbs-go" tabindex="-1">What is BBS-GO? <a class="header-anchor" href="#what-is-bbs-go" aria-label="Permalink to “What is BBS-GO?”">​</a></h2><p>BBS-GO is a lightweight self-hosted community platform for forums, Q&amp;A, and knowledge sharing. It is open source and built with Go and React.</p><h2 id="what-can-i-build-with-it" tabindex="-1">What can I build with it? <a class="header-anchor" href="#what-can-i-build-with-it" aria-label="Permalink to “What can I build with it?”">​</a></h2><p>You can use BBS-GO for public forums, Q&amp;A communities, knowledge-sharing spaces, product user communities, developer support hubs, and internal team spaces.</p><h2 id="is-bbs-go-only-a-forum" tabindex="-1">Is BBS-GO only a forum? <a class="header-anchor" href="#is-bbs-go-only-a-forum" aria-label="Permalink to “Is BBS-GO only a forum?”">​</a></h2><p>No. Forum-style discussions are one core use case, but BBS-GO also supports article publishing, accepted-answer Q&amp;A workflows, tags, categories, search, notifications, reputation mechanics, and admin operations.</p><h2 id="how-is-it-different-from-heavyweight-forum-systems" tabindex="-1">How is it different from heavyweight forum systems? <a class="header-anchor" href="#how-is-it-different-from-heavyweight-forum-systems" aria-label="Permalink to “How is it different from heavyweight forum systems?”">​</a></h2><p>BBS-GO focuses on practical self-hosted deployment, a smaller operational footprint, and a combined forum + Q&amp;A + knowledge-sharing experience. It is a good fit when chat is too noisy, docs are not interactive enough, and a large enterprise community suite feels too heavy.</p><h2 id="can-i-self-host-it" tabindex="-1">Can I self-host it? <a class="header-anchor" href="#can-i-self-host-it" aria-label="Permalink to “Can I self-host it?”">​</a></h2><p>Yes. BBS-GO is designed for self-hosted deployment. You can use Docker, release packages, or source builds.</p><h2 id="does-it-support-docker" tabindex="-1">Does it support Docker? <a class="header-anchor" href="#does-it-support-docker" aria-label="Permalink to “Does it support Docker?”">​</a></h2><p>Yes. See <a href="./installation/docker.html">Docker Deployment</a> for the compose setup and single-container command.</p><h2 id="which-database-should-i-use" tabindex="-1">Which database should I use? <a class="header-anchor" href="#which-database-should-i-use" aria-label="Permalink to “Which database should I use?”">​</a></h2><p>MySQL is recommended for production. SQLite is available for local trials and lightweight evaluation.</p><h2 id="does-it-support-multiple-languages" tabindex="-1">Does it support multiple languages? <a class="header-anchor" href="#does-it-support-multiple-languages" aria-label="Permalink to “Does it support multiple languages?”">​</a></h2><p>Yes. BBS-GO currently supports <code>en-US</code> and <code>zh-CN</code> in the web experience and server-side messages.</p><h2 id="where-can-i-try-it" tabindex="-1">Where can I try it? <a class="header-anchor" href="#where-can-i-try-it" aria-label="Permalink to “Where can I try it?”">​</a></h2><p>Visit the live demo community: <a href="https://bbs.bbs-go.com" target="_blank" rel="noreferrer">https://bbs.bbs-go.com</a></p><h2 id="where-should-i-report-issues" tabindex="-1">Where should I report issues? <a class="header-anchor" href="#where-should-i-report-issues" aria-label="Permalink to “Where should I report issues?”">​</a></h2><p>Use GitHub issues: <a href="https://github.com/mlogclub/bbs-go/issues" target="_blank" rel="noreferrer">https://github.com/mlogclub/bbs-go/issues</a></p>',22)])])}const m=a(i,[["render",r]]);export{p as __pageData,m as default};
